from __future__ import annotations

import os

from link.config import KeelPaths, Refused, read_text

HEADER = (
    "<!-- GENERATED by keel bin/link from PRINCIPLES.md + PERSONAL.md. "
    "Edit the sources, then run bin/link --write. -->"
)
MAX_BYTES = 4096
FILE_NAME = "CLAUDE.md"
RESTORE_OP = "restore-claude-md"


def build_claude_md(paths: KeelPaths) -> str:
    principles_path = os.path.join(paths.keel_home, "PRINCIPLES.md")
    if not os.path.isfile(principles_path):
        raise Refused(f"{principles_path} is missing; CLAUDE.md cannot be generated")
    text = HEADER + "\n" + _read_with_final_newline(principles_path)
    personal_path = os.path.join(paths.overlay_dir, "PERSONAL.md")
    if os.path.isfile(personal_path):
        text += "\n" + _read_with_final_newline(personal_path)
    return text


def is_generated_claude_md(path: str) -> bool:
    if os.path.islink(path) or not os.path.isfile(path):
        return False
    with open(path, encoding="utf-8", newline="") as f:
        return f.readline().rstrip("\n") == HEADER


def restore_moved_aside(path: str, backup_path: str | None) -> dict | None:
    """Move the CLAUDE.md that --write --force moved aside back; None when none is recorded, it is gone, or `path` is taken."""
    if not backup_path or not os.path.lexists(backup_path) or os.path.lexists(path):
        return None
    os.rename(backup_path, path)
    return {"op": RESTORE_OP, "path": path, "from": backup_path}


def _read_with_final_newline(path: str) -> str:
    text = read_text(path)
    return text if text.endswith("\n") else text + "\n"
